#include "cra_macro.h"

void
make_repeat_code(int n)
{
    printf("#define CRA_REPEAT1(M, p) M(0, p)\n");
    for (int i = 2; i <= n; i++)
    {
        printf("#define CRA_REPEAT%d(M, p) CRA_REPEAT%d(M, p) M(%d, p)\n", i, i - 1, i - 1);
    }
}

void
make_test_repeat_code(int n)
{
    printf("#define XX(i, x) (indexes[i] = i, n += x);\n");

    printf("int n;\n");
    printf("int indexes[%d];\n", n);

    for (int i = 0; i < n; i++)
    {
        printf("n = 0;\n");
        printf("CRA_REPEAT(XX, 1, %d)\n", i + 1);
        printf("assert_always(n == %d);\n", i + 1);
        printf("for (int i = 0; i < %d; i++)\n", i + 1);
        printf("assert_always(indexes[i] == i);\n");
    }

    printf("#undef XX\n");
}

void
make_iter_code(int n)
{
    printf("#define CRA_ITER1(M, p, ...)    M(p, __VA_ARGS__)\n");
    for (int i = 2; i <= n; i++)
    {
        printf("#define CRA_ITER%d(M, p, x, ...) M(p, x) CRA_ITER%d(M, p, __VA_ARGS__)\n", i, i - 1);
    }
}

void
make_test_iter_code(int n)
{
    printf("#define INC(_, x) +1\n\n");
    printf("int n = 0;\n");
    printf("assert_always(n == 0);\n");

    for (int i = 1; i <= n; i++)
    {
        printf("n = CRA_ITER(INC, _");
        for (int j = 1; j <= i; j++)
            printf(", x");
        printf(");\n");
        printf("assert_always(n == %d);\n", i);
    }
    printf("#undef INC\n");
}

void
make_get_i_code(int n)
{
    for (int i = 1; i <= n; i++)
        printf("#define CRA_GET_I%d(x, ...)  CRA_GET_I%d(__VA_ARGS__)\n", i, i - 1);
}

void
make_test_get_i_code(int n)
{
    int  m = 0;
    char n128[1024] = { 0 };
    for (int i = 0; i < n + 1; i++)
        m += snprintf(n128 + m, sizeof(n128) - m, ", %d", (i + 1) * 100);

    for (int j, i = 0; i < n; i++)
    {
        printf("assert_always(CRA_GET_I(%d", i);
        for (j = 0; j <= i; j++)
            printf(", %d", (j + 1) * 100);
        printf(") == %d);\n", (i + 1) * 100);
        printf("assert_always(CRA_GET_I(%d%s) == %d);\n", i, n128, (i + 1) * 100);
    }
}

void
make_get_n_code(int n)
{
    printf("#define CRA_GET_N1 CRA_GET_I0\n");
    for (int i = 2; i <= n; i++)
    {
        printf("#define CRA_GET_N%d(x, ...) x, CRA_GET_N%d(__VA_ARGS__)\n", i, i - 1);
    }
}

void
make_test_get_n_code(int n)
{
    int  m = 0;
    char n128[1024] = { 0 };
    for (int i = 0; i < n + 1; i++)
        m += snprintf(n128 + m, sizeof(n128) - m, ", %d", (i + 1) * 100);

    for (int j, i = 1; i <= n; i++)
    {
        printf("int array%da[] = {CRA_GET_N(%d", i, i);
        for (j = 1; j <= i; j++)
            printf(", %d", j * 100);
        printf(")};\n");
        printf("int array%db[] = {CRA_GET_N(%d%s)};\n", i, i, n128);
        printf("assert_always(CRA_NARRAY(array%da) == %d);\n", i, i);
        printf("assert_always(CRA_NARRAY(array%db) == %d);\n", i, i);
        printf("for (int i = 0; i < CRA_NARRAY(array%da); i++)\n", i);
        printf("{\nassert_always(array%da[i] == (i+1)*100);\nassert_always(array%da[i] == array%db[i]);\n}\n", i, i, i);
    }
}

void
make_inc_dec_code(int n)
{
    for (int i = 0; i < n; i++)
    {
        printf("#define CRA_INC%d %d\n", i, i + 1);
    }
    printf("\n");
    for (int i = n; i > 0; i--)
    {
        printf("#define CRA_DEC%d %d\n", i, i - 1);
    }
}

